9	export const DISCOVER_ENTRY_POINTS_TOOL_NAME = 'codeprep_discover_entry_points';
10	
11	export const discoverEntryPointsToolDefinition = {
12	  name: DISCOVER_ENTRY_POINTS_TOOL_NAME,
13	  description: 'Discover entry point candidates in the workspace based on the task description, enriched with native structural evidence.',
14	  inputSchema: {
15	    type: 'object',
16	    properties: {
17	      task: { type: 'string', description: 'Task or bug description to search entry points for.' },
18	      maxCandidates: { type: 'number', description: 'Maximum number of candidates to return (default: 10, max: 50).' },
19	      enrichTopN: { type: 'number', description: 'Number of top candidates to enrich with structural evidence (default: 5).' },
20	    },
21	    required: ['task'],
22	    additionalProperties: false,
23	  },
24	} as const;
25	
26	export type DiscoverEntryPointsInput = { task: string; maxCandidates?: number; enrichTopN?: number };
27	
28	function validateInput(raw: unknown): DiscoverEntryPointsInput {
29	  if (!raw || typeof raw !== 'object') throw new Error('Input must be an object');
30	  const val = raw as Record<string, unknown>;
31	  if (typeof val.task !== 'string' || !val.task.trim()) throw new Error('Field "task" must be a non-empty string');
32	  return {
33	    task: val.task.trim(),
34	    maxCandidates: typeof val.maxCandidates === 'number' ? Math.min(Math.max(val.maxCandidates, 1), 50) : 10,
35	    enrichTopN: typeof val.enrichTopN === 'number' ? Math.min(Math.max(val.enrichTopN, 1), 20) : 5,
36	  };
37	}
38	
39	async function executeDiscovery(container: McpContextContainer, input: DiscoverEntryPointsInput): Promise<McpDiscoverEntryPointsResult> {
40	  const pid = container.project.id;
41	  const disc = await container.discoverUseCase.execute({ task: input.task, projectIds: [pid], maxCandidates: input.maxCandidates });
42	  const enriched = await container.enrichUseCase.execute({ task: input.task, projectIds: [pid], candidates: disc.candidates, options: { enrichTopN: input.enrichTopN } });
43	  const confidence = evaluateContextConfidence({ candidates: enriched });
44	  const suggestedPackStrategy = resolveAdaptivePackMode(confidence);
45	  return {
46	    task: input.task,
47	    candidates: transformCandidates(enriched),
48	    confidence,
49	    suggestedPackStrategy,
50	    warnings: disc.warnings.map((w) => w.message),
51	  };
52	}
53	
54	export async function handleDiscoverEntryPoints(container: McpContextContainer, rawInput: unknown): Promise<McpDiscoverEntryPointsResult> {
55	  const input = validateInput(rawInput);
56	  stderrLog('Executing codeprep_discover_entry_points: ' + input.task.slice(0, 50));
57	  try {
58	    const res = await executeDiscovery(container, input);
59	    stderrLog('Discovered ' + res.candidates.length + ' entry point candidates');
60	    return res;
61	  } catch (error) {
62	    stderrError('Failed to discover entry points', error);
63	    throw error;
64	  }
65	}
